import{_ as t,o as e,c as a,ag as _}from"./chunks/framework.DaAXJYxM.js";const u=JSON.parse('{"title":"第36章 翻手机","description":"","frontmatter":{},"headers":[],"relativePath":"第36章_翻手机.md","filePath":"第36章_翻手机.md"}'),o={name:"第36章_翻手机.md"};function r(n,p,s,c,i,d){return e(),a("div",null,[...p[0]||(p[0]=[_('<h1 id="第36章-翻手机" tabindex="-1">第36章 翻手机 <a class="header-anchor" href="#第36章-翻手机" aria-label="Permalink to &quot;第36章 翻手机&quot;">​</a></h1><p>开学那天我回市里，在车上睡了一路。</p><p>到宿舍是下午，屋里还没人。我把包放下，先给她发了一条：我到了。</p><p>她晚上十点回：嗯。</p><p>就一个字。</p><p>二月最后那几天，她说话的方式变了一点。</p><p>以前她会跟我说时间。她说几点下课，几点吃饭，几点她妈会进屋。她会提前一天告诉我明天能不能聊。有一次她还专门算过，说她们班晚自习七点二十结束，她要在教室里坐到七点五十才走，因为七点五十以后她班主任不去走廊。</p><p>那几天她什么都不报了。</p><p>她什么时候上线我不知道，她什么时候走我也不知道。我发消息过去，有时候隔两小时回，有时候第二天回。</p><p>我不问。她说什么我接什么。</p><p>那阵子里有一件小事，我一直没跟别人说过。</p><p>开学那天我在宿舍整理桌子，把从家里带的那个搪瓷杯放上去。杯子边上磕掉一块瓷，露出底下黑色的铁，是我奶奶用了二十年那只的同款。</p><p>我把它放好的时候，忽然想起去年她绕了半个操场给我送来的那瓶水。</p><p>那之后我每天用那个杯子喝水。我说不清这是什么毛病。</p><p>三月初有一天，她忽然说了。</p><p>她说，我把那天为什么没来，跟你说一下。</p><p>我说，你不用讲。</p><p>她说，我想讲。</p><p>她说，那天早上我出了门。</p><p>她说，我走到半路，我妈打电话给我班主任。</p><p>我说，然后呢。</p><p>她说，然后我回家，她没问我一句。</p><p>她说，她把手机从我手里拿过去，放到我桌上，插好充电。</p><p>她说，她说，你想聊就聊吧。</p><p>我看着这几句，等了很久才回。</p><p>因为我以为她妈是骂了她。我甚至替她想了三种她妈骂她的说法，我想好了如果她哭，我接哪一句。</p><p>一种都没用上。</p><p>我回：她没骂你？</p><p>她说，没有。</p><p>她说，她那天晚上切了一盘水果放我房间门口。</p><p>她说，第二天早上她把早饭端到我桌上，说她以前太凶了。</p><p>她说，从那天起她进我房间不敲门了，直接推门。</p><p>她说，我把门锁了两次，第二天她就把锁卸了。</p><p>她说，她说这样不藏着掖着，多好。</p><p>我坐在那里，很久没动。</p><p>我想象得出来那个画面。一盘水果，一只碗，早饭放在桌上，门开着。一件一件，全是好意。</p><p>那天晚上她说的最后两句是这个。</p><p>她说，你知道最难受的是什么吗。</p><p>我说，不知道。</p><p>她说，是她不查。</p><p>她说，她要查，我还能恨她。</p><p>她说，她现在不查，我就得自己拦着自己。</p><p>我说，那你不聊了？</p><p>她说，我没说不聊。</p><p>她说，我只是以后不约了。</p><p>我说，那你什么时候能聊。</p><p>她说，看我心情。</p><p>她说，你别逼我。</p><p>我说，我没逼。</p><p>她说，你这句话就是逼。</p><p>那天夜里我把这几句抄在本子上。</p><p>我抄得很慢。抄到那句&quot;她要查，我还能恨她&quot;的时候，我停下来想了一会儿。</p><p>我想的是我自己家里。我妈打电话来那天，奶奶说&quot;反正是一个同学&quot;，我妈在电话那头&quot;哦&quot;了一声。</p><p>她那天没有问我名字，没有问我长什么样，没有问我在哪个班。</p><p>她也什么都没查。</p><p>我那天晚上第一次想到一件事：不查，可能比查更难对付。</p><p>因为查是有对手的。不查，对手就变成你自己。</p><p>那之后我每次拿起手机，都会先想一下：我做的事，是不是也要自己拦着。</p><p>我把这个念头压下去了。</p><p>第二天早上她来了一条，说的是别的事。</p><p>她说，你看这个。后面是一张图，是她买的一个小东西，塑料的，包装上有一道很细的白痕。</p><p>她说，商家说是运输划痕，只肯赔十五。</p><p>她说，你说我要不要退。</p><p>我说，退。</p><p>她说，退了我要等到明年。</p><p>我说，那就不退。</p><p>我说，你把它对着灯看，看那道痕是在膜上还是在料上。</p><p>她说，怎么看。</p><p>我说，关灯，举到窗外，让光斜着过去。</p><p>她过了两分钟发了一张照片过来。黑乎乎的，什么也看不清。</p><p>她说，看不见。</p><p>我说，你手抖。</p><p>她说，风大。</p><p>我说，你在哪吹风。</p><p>她说，阳台上。</p><p>她说，我不敢在屋里弄。</p><p>那天我们算了二十分钟。</p><p>算完她说，好，不退了。</p><p>我说，嗯。</p><p>她说，谢谢。</p><p>我说，谢什么。</p><p>她说，谢你帮我算。</p><p>我看着这一句，心里有点说不清的东西。</p><p>她谢我，是因为我帮她算了一笔十五块的账。</p><p>她没来那天，我在河边石凳上从九点坐到五点，四趟车我都数过。</p><p>这两件事在她的账本上，大概是一样重的。</p><p>那天夜里我把这件事想得很清楚。</p><p>一个人愿意跟你算十五块，不愿意告诉你她那天在不在家。这不是她坏。这是她能给的只有十五块。</p><p>我把这句写下来，写完又划掉了。</p><p>划掉是因为我意识到：我一开始记她的账，我就已经输了。</p><p>过了几天，她发来一张照片。</p><p>照片里是一个房间，拍得很斜。一张床，被子叠成一个方块，靠墙一张书桌，桌上什么也没有。门在画面右边，开着。</p><p>她说，这就是我现在的房间。</p><p>我说，挺干净的。</p><p>她说，你看桌上。</p><p>我把照片放大。桌上什么都没有。没有手机，没有杯子，没有堆起来的书。</p><p>我说，桌上是空的。</p><p>她说，对。</p><p>她说，她说她这样我是自由的。</p><p>我说，那你晚上用什么。</p><p>她没回这一句。</p><p>隔了很久，她发了一句别的。</p><p>她说，以前我桌上东西很多，笔、本子、剪刀、一堆乱纸。</p><p>她说，现在什么都没有，我反而不知道把手往哪放。</p><p>那天我把这张照片看了很多遍。</p><p>一个房间干净到没有东西可放，一个人坐在那里，手不知道往哪里放。</p><p>这就是我那年真正开始理解她的地方。</p><p>不是她哭，不是她骂人，是她给我看一张桌上什么都没有的照片。</p><p>那天晚上我把手机里的照片存了下来。</p><p>存完我想了一下，乜不太对。我又点开，看到照片左下角有一点反光，那是玻璃门。</p><p>她拍这张照片的时候，站在门外。</p><p>也就是说，她那天只能拍到开了门的房间。</p><p>我把这一点记在心里，没问她。</p>',113)])])}const m=t(o,[["render",r]]);export{u as __pageData,m as default};
